session_start();require 'config/database.php';if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;}$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM custom_quizzes WHERE id=? AND creator_id=?');$s->execute([$id,$_SESSION['user_id']]);$quiz=$s->fetch();if(!$quiz)die('Quiz not found.');$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){$amount=max(1,min(25,(int)$_POST['amount']));$difficulty=in_array($_POST['difficulty'],['easy','medium','hard'])?$_POST['difficulty']:'easy';$url='https://opentdb.com/api.php?amount='.$amount.'&type=multiple&difficulty='.$difficulty.'&category=18';$json=false;
if(function_exists('curl_init')){$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>12,CURLOPT_USERAGENT=>'QuizCode/1.0']);$json=curl_exec($ch);curl_close($ch);} elseif(ini_get('allow_url_fopen')) {$json=@file_get_contents($url);}
$data=$json?json_decode($json,true):null;if($data&&($data['response_code']??1)===0){foreach($data['results'] as $r){$correct=html_entity_decode($r['correct_answer'],ENT_QUOTES|ENT_HTML5);$opts=array_map(fn($x)=>html_entity_decode($x,ENT_QUOTES|ENT_HTML5),$r['incorrect_answers']);$opts[]=$correct;shuffle($opts);$letter=['A','B','C','D'][array_search($correct,$opts)];$q=$pdo->prepare('INSERT INTO custom_questions(quiz_id,question_text,option_a,option_b,option_c,option_d,correct_answer,time_limit,source) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$id,html_entity_decode($r['question'],ENT_QUOTES|ENT_HTML5),$opts[0],$opts[1],$opts[2],$opts[3],$letter,max(5,min(300,(int)$_POST['time_limit'])),'OpenTDB']);}$msg="$amount API questions imported.";}else{$msg='API could not return questions right now.';}}
$pageTitle='API Import';include 'includes/header.php';?><h2>Import Questions from API</h2><p>Imports multiple-choice <b>Science: Computers</b> questions from Open Trivia DB into your MySQL quiz.</p><?php if($msg):?><div class="alert alert-info"><?=$msg?></div><?php endif;?><form method="post" class="card p-4"><label>Number of questions</label><input type="number" name="amount" min="1" max="25" value="5" class="form-control mb-3"><label>Difficulty</label><select name="difficulty" class="form-select mb-3"><option>easy</option><option>medium</option><option>hard</option></select><label>Timer for imported items</label><div class="input-group mb-3"><input type="number" name="time_limit" min="5" max="300" value="30" class="form-control"><span class="input-group-text">seconds</span></div><button class="btn btn-success">Import from API</button></form><a class="btn btn-link" href="edit_quiz.php?id=<?=$id?>">Back to quiz</a><?php include 'includes/footer.php';?>